<?php $vals=[]; foreach($settings as $s) $vals[$s['key']]=$s['value']; $defaults=['scan_profile'=>config('guard.scan_profile'),'timer_scan_profile'=>config('guard.timer_scan_profile'),'scan_roots'=>implode(',',config('guard.scan_roots')),'quarantine_path'=>config('guard.quarantine_path'),'scan_interval_minutes'=>config('guard.scan_interval_minutes'),'web_actions_enabled'=>config('guard.web_actions_enabled')?'true':'false','max_file_read_bytes'=>config('guard.max_file_read_bytes'),'backup_integration_enabled'=>config('guard.backup_integration_enabled')?'true':'false','backup_provider'=>config('guard.backup_provider'),'ispmanager_detected'=>config('guard.ispmanager_detected')?'true':'false','backup_root'=>config('guard.backup_root'),'backup_browser_enabled'=>config('guard.backup_browser_enabled')?'true':'false','backup_restore_enabled'=>config('guard.backup_restore_enabled')?'true':'false','restore_current_file_to_quarantine'=>config('guard.restore_current_file_to_quarantine')?'true':'false']; ob_start(); ?>
<h1><?= e(t('Settings')) ?></h1><p class="muted"><?= e(t('Settings are stored in DB for the MVP; deployment environment variables remain authoritative where config reads env directly.')) ?></p>
<form method="post" class="card"><h2><?= e(t('Scanning')) ?></h2><?php foreach(array_slice($defaults,0,7,true) as $k=>$v): ?><label><?= e($k) ?><br><input class="input" style="width:100%" name="settings[<?= e($k) ?>]" value="<?= e($vals[$k] ?? $v) ?>"></label><br><br><?php endforeach ?><h2><?= e(t('Backups')) ?></h2><p class="muted"><?= e(t('Enable ISPmanager/custom backup browser separately from restore. Web restore is disabled by default; when disabled the UI shows the exact CLI command.')) ?></p><?php foreach(array_slice($defaults,7,null,true) as $k=>$v): ?><label><?= e($k) ?><br><?php if($k==='backup_provider'): ?><select class="input" name="settings[<?= e($k) ?>]"><?php foreach(['ispmanager'=>'ISPmanager','custom'=>'Custom backup folder','disabled'=>'Disabled'] as $val=>$label): ?><option value="<?= e($val) ?>" <?= (($vals[$k] ?? $v)===$val)?'selected':'' ?>><?= e(t($label)) ?></option><?php endforeach ?></select><?php else: ?><input class="input" style="width:100%" name="settings[<?= e($k) ?>]" value="<?= e($vals[$k] ?? $v) ?>"><?php endif ?></label><br><br><?php endforeach ?><button class="btn"><?= e(t('Save')) ?></button></form>
<div class="card"><h2><?= e(t('Telegram alerts')) ?></h2><p class="muted"><?= e(t('Configured via JURA_TELEGRAM_ENABLED / JURA_TELEGRAM_BOT_TOKEN / JURA_TELEGRAM_CHAT_ID in .env (not editable here — see README). New critical/high findings, new web-root files from untrusted IPs, and new cron jobs are sent here after each scan.')) ?></p><p><b><?= e(t('Status:')) ?></b> <?= config('guard.telegram_enabled') && config('guard.telegram_bot_token') && config('guard.telegram_chat_id') ? e(t('enabled')) : e(t('disabled')) ?></p><?php if($telegramTestResult): ?><p style="color:<?= $telegramTestResult['ok']?'#4ade80':'#fca5a5' ?>"><?= $telegramTestResult['ok'] ? e(t('Test message sent.')) : e(t('Test failed:')).' '.e($telegramTestResult['error'] ?? '') ?></p><?php endif ?><form method="post" action="/settings/telegram-test"><button class="btn"><?= e(t('Send test message')) ?></button></form><p><a class="btn" href="/trusted-ips"><?= e(t('Manage trusted IPs')) ?></a></p></div>
<div class="card"><h2><?= e(t('AI provider')) ?></h2><p class="muted"><?= e(t('Configured via .env (not editable here — see README): JURA_AI_PROVIDER=openai|anthropic selects the provider, JURA_AI_MODEL sets the model name. For OpenAI: JURA_OPENAI_ENABLED / JURA_OPENAI_API_KEY. For Anthropic (Claude): JURA_ANTHROPIC_ENABLED / JURA_ANTHROPIC_API_KEY. JURA_AI_SIGNATURES_ENABLED turns on real AI calls for "Generate signature with AI"; when off (or no provider configured) it still creates a draft placeholder for manual review instead of failing.')) ?></p><p><b><?= e(t('Status:')) ?></b> <?= e(strtoupper((string)config('guard.ai_provider'))) ?>, <?= App\Modules\Ai\AiClient::fromConfig() ? e(t('enabled')) : e(t('disabled')) ?></p><p class="muted"><?= e(t('Automatically quarantine obvious shells (matched a known signature, or uploaded from an IP not in the trusted list) right after each scan: JURA_AUTO_QUARANTINE_OBVIOUS_SHELLS (default off). Quarantine is reversible via Restore.')) ?></p><p><b><?= e(t('Status:')) ?></b> <?= config('guard.auto_quarantine_obvious_shells') ? e(t('enabled')) : e(t('disabled')) ?></p><p class="muted"><?= e(t('AI chat (nav bar link, hidden when off): JURA_AI_CHAT_ENABLED. Quarantine, delete, and trust-IP actions requested in chat always show a confirmation step before anything actually runs.')) ?></p><p><b><?= e(t('Status:')) ?></b> <?= config('guard.ai_chat_enabled') ? e(t('enabled')) : e(t('disabled')) ?></p></div>
